questionvariables.text:
/* BIG WIN */
bigWinPrize:rand_with_step(110,200,10);
bigWinCost:rand_with_step(30,42,3)/10;
bigWinRate:rand([2,12/5,5/2,3])/100;

bigWinProfit:float(bigWinPrize-(bigWinCost/bigWinRate));

/* LITTLE LUCKY */
littleLuckyPrize:rand_with_step(10,50,10);
littleLuckyCostFrac: if integerp(bigWinCost*(5/3)) then 1/rand([5,6,10,12]) else 1/rand([5,6,10]);
littleLuckyCost:littleLuckyCostFrac*bigWinCost;
littleLuckyRate: if integerp(littleLuckyCost*(25/3)) then rand([6,8])/100 else if integerp(littleLuckyCost*10) then rand([5,8])/100 else if integerp(littleLuckyCost*(100/3)) then rand([5,6])/100 else 1/20;

littleLuckyProfit:float(littleLuckyPrize-(littleLuckyCost/littleLuckyRate));

/* To insure there is always a unique correct answer, redo LITTLE LUCKY if it is has the same profit as BIG WIN */

while littleLuckyProfit=bigWinProfit do ((littleLuckyPrize:rand_with_step(10,50,10)) and (littleLuckyCostFrac: if integerp(bigWinCost*(5/3)) then 1/rand([5,6,10,12]) else 1/rand([5,6,10])) and (littleLuckyCost:littleLuckyCostFrac*bigWinCost) and (littleLuckyRate: if integerp(littleLuckyCost*(25/3)) then rand([6,8])/100 else if integerp(littleLuckyCost*10) then rand([5,8])/100 else if integerp(littleLuckyCost*(100/3)) then rand([5,6])/100 else 1/20) and (littleLuckyProfit:float(littleLuckyPrize-(littleLuckyCost/littleLuckyRate))));

/* ALL IN ONE */
allInOnePrize:rand_with_step(60,90,10);
allInOneCost:rand([6/5,7/5,3/2,8/5,9/5,11/5,12/5,5/2,13/5,14/5]);
allInOneTicketNo: if integerp(allInOneCost*2) then rand([6,8,12,14]) else rand([10,15]);
allInOneRate: if integerp(allInOneCost*(100/3)) then rand_with_prohib(3,5,[littleLuckyRate*100])/100 else rand_with_prohib(4,5,[littleLuckyRate*100])/100;

allInOneProfit:float(allInOnePrize-(allInOneCost/allInOneRate));

/* To insure there is always a unique correct answer, redo ALL IN ONE if it is has the same profit as BIG WIN or LITTLE LUCKY */

while (allInOneProfit=bigWinProfit or allInOneProfit=littleLuckyProfit) do ((allInOnePrize:rand_with_step(60,100,10)) and (allInOneCost:rand([6/5,7/5,3/2,8/5,9/5,11/5,12/5,5/2,13/5,14/5])) and (allInOneTicketNo: if integerp(allInOneCost*2) then rand([6,8,12,14]) else rand([10,15])) and (allInOneRate: if integerp(allInOneCost*(100/3)) then rand_with_prohib(3,5,[littleLuckyRate*100])/100 else rand_with_prohib(4,5,[littleLuckyRate*100])/100) and (allInOneProfit:float(allInOnePrize-(allInOneCost/allInOneRate))));

/* Best Lottery and respective profit */
bigWinBest: if bigWinProfit>=littleLuckyProfit and bigWinProfit>=allInOneProfit then true else false;
littleLuckyBest: if littleLuckyProfit>=allInOneProfit and littleLuckyProfit>=bigWinProfit then true else false;
allInOneBest: if allInOneProfit>=bigWinProfit and allInOneProfit>=littleLuckyProfit then true else false;

bestLottery: if bigWinBest then "BIG WIN" else if littleLuckyBest then "LITTLE LUCKY" else "ALL IN ONE";
bestProfit: if bigWinBest then bigWinProfit else if littleLuckyBest then littleLuckyProfit else allInOneProfit;

