/* Node 5: If lottery and largest profit incorrect, check if given largest profit matches given lottery (+2) */
studentProfit: if ans1="BIG WIN" then bigWinProfit else if ans1="LITTLE LUCKY" then littleLuckyProfit else allInOneProfit;

/* Node 6: Check whether student has calculated average profit per ticket of given lottery (+1) */
bigWinProfitPerTicket:bigWinPrize*bigWinRate-bigWinCost;
littleLuckyProfitPerTicket:littleLuckyPrize*littleLuckyRate-littleLuckyCost;
allInOneProfitPerTicket:allInOnePrize*allInOneRate-allInOneCost;
studentProfitPerTicket: if ans1="BIG WIN" then bigWinProfitPerTicket else if ans1="LITTLE LUCKY" then littleLuckyProfitPerTicket else allInOneProfitPerTicket;

/* Node 7: Conversion mistake on BIG WIN; treating 2% as 1/2, etc. */
node7_test: if ans1="BIG WIN" and decimalplaces(ans2,2)=decimalplaces(bigWinPrize-(bigWinCost*100*bigWinRate),2) then 1 else 0;

/* Node 8: Common mistake on LITTLE LUCKY, treating 0.05 as 1/5, etc. */
node8_test: if ans1="LITTLE LUCKY" and decimalplaces(ans2,2)=decimalplaces(littleLuckyPrize-(littleLuckyCost*100*littleLuckyRate),2) then 1 else 0;

/* Node 9: Common mistake on ALL IN ONE, treating 1/25 as 0.25, etc. */
node9_test: if ans1="ALL IN ONE" and decimalplaces(ans2,2)=decimalplaces(allInOnePrize-(allInOneCost*100*allInOneRate),2) then 1 else 0;
